sys_script.script:
(function executeRule(current, previous) {
    // Safety: only act if the servicing ticket is actually closed
    if ((current.ticket_status + '') !== 'closed')
        return;

    // Must have a linked tracker
    if (!current.vehicle_tracker)
        return;

    // Load the related Vehicle Tracker
    var tr = new GlideRecord('x_746154_loaner_0_vehicle_tracker');
    if (!tr.get(current.vehicle_tracker))
        return; // tracker not found

    // Values to sync onto the tracker
    var newVehicleStatus = (current.vehicle_status + ''); // copy from servicing
    var newTrackerStatus = 'closed';                      // tracker_status closed value (confirm in dictionary)

    var changed = false;

    // 1) Make tracker.vehicle_status match servicing.vehicle_status
    if ((tr.vehicle_status + '') !== newVehicleStatus) {
        tr.vehicle_status = newVehicleStatus;
        changed = true;
    }

    // 2) Set tracker.tracker_status to Closed
    if ((tr.tracker_status + '') !== newTrackerStatus) {
        tr.tracker_status = newTrackerStatus;
        changed = true;
    }

    if (changed) tr.update();
})(current, previous);
